function maxFlow(nodes, edges, s, t){
  var cap={};
  edges.forEach(function(e){ var k=e[0]+'|'+e[1]; cap[k]=(cap[k]||0)+e[2]; });
  function c(u,v){ return cap[u+'|'+v]||0; }
  var flow=0;
  while(true){
    var prev={}; prev[s]=-1; var q=[s]; var vis={}; vis[s]=1;
    while(q.length){ var u=q.shift(); if(u===t) break;
      nodes.forEach(function(v){ if(!vis[v] && c(u,v)>0){ vis[v]=1; prev[v]=u; q.push(v); } }); }
    if(!vis[t]) break;
    var path=[]; var v=t; while(v!==s){ path.push(v); v=prev[v]; } path.push(s); path.reverse();
    var bot=Infinity; for(var i=0;i<path.length-1;i++) bot=Math.min(bot, c(path[i],path[i+1]));
    for(var i=0;i<path.length-1;i++){ var uu=path[i], vv=path[i+1]; cap[uu+'|'+vv]-=bot; cap[vv+'|'+uu]=(cap[vv+'|'+uu]||0)+bot; }
    flow+=bot;
  }
  return flow;
}
var EXPORTS={maxFlow:maxFlow};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.MaxFlowForgePure = EXPORTS; }
